90	class MainTheatreRuntime {
91	  private static _instance: MainTheatreRuntime | null = null;
92	
93	  private readonly _rig = new MainSceneRig();
94	  private readonly _stateSource: Record<string, unknown> | null;
95	  private readonly _project: TheatreProjectPort<
96	    MainTheatreValue,
97	    MainTheatreProps
98	  >;
99	  private readonly _objectBySheetId = new Map<
100	    MainTheatreSheetId,
101	    MainTheatreObject
102	  >();
103	  private readonly _sequenceBySheetId = new Map<
104	    MainTheatreSheetId,
105	    TheatreSequencePort
106	  >();
107	  private readonly _lengthBySheetId = new Map<MainTheatreSheetId, number>();
108	  private readonly _playbackRangeBySheetId = new Map<
109	    MainTheatreSheetId,
110	    MainTheatrePlaybackRange
111	  >();
112	  private readonly _cameraPlaybackRangeBySheetId = new Map<
113	    MainTheatreSheetId,
114	    MainTheatrePlaybackRange
115	  >();
116	  private readonly _autoplayRuntime: MainTheatreAutoplayRuntime;
117	
118	  private constructor() {
119	    this._autoplayRuntime = new MainTheatreAutoplayRuntime(
120	      (engine, values) => this._applyState(engine, values),
121	    );
122	    this._stateSource = resolveMainTheatreStateSource();
123	    this._project = TheatreProjectSession.open<
124	      MainTheatreValue,
125	      MainTheatreProps
126	    >(
127	      MAIN_THEATRE_PROJECT_ID,
128	      this._stateSource ? { state: this._stateSource } : undefined,
129	    );
130	    MAIN_THEATRE_SHEET_IDS.forEach((sheetId) => {
131	      const sheet = TheatreSheetSession.open(this._project, sheetId);
132	      const object = sheet.object(
133	        MAIN_THEATRE_OBJECT_ID,
134	        mergeMainSceneState(),
135	        {
136	          reconfigure: true,
137	        },
138	      );
139	      const sequenceLength = this._resolveSheetLength(sheetId, sheet.sequence);
140	      const playbackRange = this._resolvePreviewRange(sheetId, sequenceLength);
141	      const cameraPlaybackRange = this._resolveCameraPreviewRange(
142	        sheetId,
143	        sequenceLength,
144	      );
145	      this._objectBySheetId.set(sheetId, object);
146	      this._sequenceBySheetId.set(sheetId, sheet.sequence);
147	      this._lengthBySheetId.set(sheetId, sequenceLength);
148	      if (playbackRange) {
149	        this._playbackRangeBySheetId.set(sheetId, playbackRange);
150	      }
151	      if (cameraPlaybackRange) {
152	        this._cameraPlaybackRangeBySheetId.set(sheetId, cameraPlaybackRange);
153	      }
154	    });
155	  }
156	
157	  static getInstance(): MainTheatreRuntime {
158	    if (MainTheatreRuntime._instance) return MainTheatreRuntime._instance;
159	    MainTheatreRuntime._instance = new MainTheatreRuntime();
160	    return MainTheatreRuntime._instance;
