163	  syncSceneToEngine(
164	    engine: Engine,
165	    sceneKey: MainSceneSectionKey,
166	    progress: number,
167	  ): MainSceneProgressState | null {
168	    const resolvedState = this.resolveSceneState(sceneKey, progress);
169	    this._rig.apply(
170	      engine,
171	      mergeMainSceneState(resolvedState ?? DEFAULT_MAIN_SCENE_STATE),
172	    );
173	    return this.resolveSceneProgressState(sceneKey, progress);
174	  }
175	
176	  readState(sheetId: MainTheatreSheetId, position = 0): MainTheatreValue {
177	    const sequence = this._sequenceBySheetId.get(sheetId);
178	    const object = this._objectBySheetId.get(sheetId);
179	    if (!sequence || !object) return mergeMainSceneState();
180	    const previousPosition = sequence.position;
181	    sequence.position = this._clampPosition(
182	      position,
183	      this._lengthBySheetId.get(sheetId) ?? 0,
184	    );
185	    const state = mergeMainSceneState(object.value);
186	    sequence.position = previousPosition;
187	    return state;
188	  }
189	
190	  readPlaybackRange(sheetId: MainTheatreSheetId): MainTheatrePlaybackRange {
191	    const length = this._lengthBySheetId.get(sheetId) ?? 0;
192	    return this._resolvePlaybackRange(sheetId, length);
193	  }
