195	  readCameraPlaybackRange(
196	    sheetId: MainTheatreSheetId,
197	  ): MainTheatrePlaybackRange {
198	    const length = this._lengthBySheetId.get(sheetId) ?? 0;
199	    return this._resolveCameraPlaybackRange(sheetId, length);
200	  }
201	
202	  resolveSceneProgressState(
203	    sceneKey: MainSceneSectionKey,
204	    progress: number,
205	  ): MainSceneProgressState | null {
206	    const resolvedSteps = this._resolveSceneSteps(sceneKey)
207	      .map((step) => this._resolveStep(step))
208	      .filter((step): step is MainResolvedTheatrePlaybackStep => step != null);
209	    if (resolvedSteps.length === 0) return null;
210	    const clampedProgress = this._clampPosition(progress, 1);
211	    for (const step of resolvedSteps) {
212	      if (!this._isProgressWithinRange(clampedProgress, step.progressRange)) {
213	        continue;
214	      }
215	      const localProgress = this._resolveLocalProgress(
216	        clampedProgress,
217	        step.progressRange,
218	      );
219	      return {
220	        sheetId: step.sheetId,
221	        localProgress,
222	      };
223	    }
224	    return null;
225	  }
