227	  readSceneDebugSnapshot(
228	    sceneKey: MainSceneSectionKey,
229	    progress: number,
230	  ): MainSceneDebugSnapshot | null {
231	    const state = this.resolveSceneProgressState(sceneKey, progress);
232	    if (!state) return null;
233	    const length = this._lengthBySheetId.get(state.sheetId) ?? 0;
234	    const range = this._resolvePlaybackRange(state.sheetId, length);
235	    const sheetPosition =
236	      range.start +
237	      (range.end - range.start) * this._clampPosition(state.localProgress, 1);
238	    return {
239	      sceneKey,
240	      sheetId: state.sheetId,
241	      localProgress: state.localProgress,
242	      sheetPosition,
243	      rangeStart: range.start,
244	      rangeEnd: range.end,
245	      tracks: this._resolveDebugTrackSnapshots(state.sheetId, sheetPosition),
246	    };
247	  }
