251	    progress: number,
252	  ): MainTheatreValue | null {
253	    const state = this.resolveSceneProgressState(sceneKey, progress);
254	    if (!state) return null;
255	    const length = this._lengthBySheetId.get(state.sheetId) ?? 0;
256	    const range = this._resolvePlaybackRange(state.sheetId, length);
257	    const position =
258	      range.start +
259	      (range.end - range.start) * this._clampPosition(state.localProgress, 1);
260	    return this.readState(state.sheetId, position);
