309	  startIntroActionPhaseTwoAutoplay(engine: Engine): Promise<void> {
310	    const range = this._resolveIntroActionPhaseTwoRange();
311	    return this._startSheetAutoplayRange(engine, "introAction", range, {
312	      rate: MAIN_INTRO_ACTION_PHASE_TWO_RATE,
313	      fallbackSync: (targetEngine) =>
314	        this._syncIntroActionEndState(targetEngine, range.end),
315	      completeSync: (targetEngine) =>
316	        this._syncIntroActionEndState(targetEngine, range.end),
317	    });
318	  }
319	
320	  applyBootState(engine: Engine): void {
321	    const introRange = this._resolveCameraPlaybackRange(
322	      "intro",
323	      this._lengthBySheetId.get("intro") ?? 0,
