327	
328	  private _resolveStep(
329	    step: MainTheatrePlaybackStep,
330	  ): MainResolvedTheatrePlaybackStep | null {
331	    const sequence = this._sequenceBySheetId.get(step.sheetId);
332	    if (!sequence) return null;
333	    const length = this._lengthBySheetId.get(step.sheetId) ?? 0;
334	    const range =
335	      step.playbackRangeSource === "camera"
336	        ? this._resolveCameraPlaybackRange(step.sheetId, length)
337	        : this._resolveConfiguredPlaybackRange(
338	            step.playbackRange,
339	            step.sheetId,
340	            length,
341	          );
342	    return {
343	      sheetId: step.sheetId,
344	      range,
345	      progressRange: this._resolveProgressRange(step.progressRange),
346	    };
347	  }
348	
349	  private _resolvePlaybackRange(
350	    sheetId: MainTheatreSheetId,
351	    length: number,
352	  ): MainTheatrePlaybackRange {
353	    const configuredRange =
354	      this._playbackRangeBySheetId.get(sheetId) ??
355	      MAIN_THEATRE_PLAYBACK_RANGES[sheetId] ??
356	      null;
357	    if (!configuredRange) {
358	      return {
359	        start: 0,
360	        end: Number.isFinite(length) && length > 0 ? length : 0,
361	      };
362	    }
363	    return {
364	      start: this._clampPosition(configuredRange.start, length),
365	      end: this._clampPosition(configuredRange.end, length),
366	    };
367	  }
368	
369	  private _resolveCameraPlaybackRange(
370	    sheetId: MainTheatreSheetId,
371	    length: number,
372	  ): MainTheatrePlaybackRange {
373	    const configuredRange =
374	      this._cameraPlaybackRangeBySheetId.get(sheetId) ??
375	      this._playbackRangeBySheetId.get(sheetId) ??
376	      MAIN_THEATRE_PLAYBACK_RANGES[sheetId] ??
377	      null;
378	    if (!configuredRange) {
379	      return {
380	        start: 0,
381	        end: Number.isFinite(length) && length > 0 ? length : 0,
382	      };
383	    }
384	    return {
385	      start: this._clampPosition(configuredRange.start, length),
386	      end: this._clampPosition(configuredRange.end, length),
387	    };
388	  }
389	
390	  private _resolveSceneSteps(
391	    sceneKey: MainSceneSectionKey,
392	  ): readonly MainTheatrePlaybackStep[] {
393	    return MAIN_SCENE_THEATRE_STEPS[sceneKey] ?? [];
394	  }
395	
396	  private _resolveConfiguredPlaybackRange(
397	    configuredRange: MainTheatrePlaybackRange | undefined,
398	    sheetId: MainTheatreSheetId,
399	    length: number,
400	  ): MainTheatrePlaybackRange {
401	    if (!configuredRange) {
402	      return this._resolvePlaybackRange(sheetId, length);
403	    }
404	    return {
405	      start: this._clampPosition(configuredRange.start, length),
406	      end: this._clampPosition(configuredRange.end, length),
407	    };
408	  }
409	
410	  private _resolveProgressRange(
411	    progressRange: MainSceneProgressRange | undefined,
412	  ): MainSceneProgressRange {
413	    if (!progressRange) {
414	      return { start: 0, end: 1 };
415	    }
416	    const start = this._clampPosition(progressRange.start, 1);
417	    const end = this._clampPosition(progressRange.end, 1);
418	    if (end <= start) {
419	      return { start, end: 1 };
420	    }
421	    return { start, end };
422	  }
423	
424	  private _isProgressWithinRange(
425	    progress: number,
426	    range: MainSceneProgressRange,
427	  ): boolean {
428	    if (progress < range.start) return false;
429	    if (progress > range.end && range.end < 1) return false;
430	    return true;
431	  }
432	
433	  private _resolveLocalProgress(
434	    progress: number,
435	    range: MainSceneProgressRange,
436	  ): number {
437	    const span = Math.max(range.end - range.start, Number.EPSILON);
438	    return this._clampPosition((progress - range.start) / span, 1);
439	  }
440	
441	  private _resolveSheetLength(
442	    sheetId: MainTheatreSheetId,
443	    sequence: TheatreSequencePort,
444	  ): number {
445	    const directLength =
446	      typeof sequence.length === "number" ? sequence.length : null;
447	    if (
448	      directLength != null &&
449	      Number.isFinite(directLength) &&
