136	function triggerStoryStats(): void {
137	  const items = Array.from(
138	    document.querySelectorAll<HTMLElement>(STORY_STAT_SELECTOR),
139	  );
140	  if (!items.length) return;
141	
142	  items.forEach((el, i) => {
143	    const target = Number(el.dataset.countTo ?? 0);
144	    let startTime: number | null = null;
145	
146	    function tick(ts: number): void {
147	      if (startTime === null) startTime = ts;
148	      const t = Math.min((ts - startTime) / STORY_STAT_DURATION, 1);
149	      const eased = 1 - Math.pow(1 - t, 3);
150	      el.textContent = Math.round(eased * target).toString();
151	      if (t < 1) requestAnimationFrame(tick);
152	    }
153	
154	    window.setTimeout(() => requestAnimationFrame(tick), i * STORY_STAT_STAGGER);
155	  });
156	}
