310	      video.pause();
311	      video.currentTime = 0;
312	    };
313	    const drainAndPause = (): void => {
314	      const p = pendingPlay;
315	      pendingPlay = null;
316	      if (p !== null) {
317	        void p.then(() => {
318	          if (!isHovered) safePause();
319	        });
320	      } else {
321	        safePause();
322	      }
323	    };
324	
325	    const onEnter = (): void => {
326	      isHovered = true;
327	      if (!video.src) {
328	        video.src = videoUrl;
