423	    mainSceneDomState.isContactActionsVisible = shouldShow;
424	    mainSceneDomState.contactActionTimers = clearTimers(
425	      mainSceneDomState.contactActionTimers,
426	    );
427	    const queue = shouldShow ? actionItems : actionItems.slice().reverse();
428	    const delayStep = shouldShow
429	      ? CONTACT_HEAD_TRANSITION.revealStagger
430	      : CONTACT_HEAD_TRANSITION.hideStagger;
431	    queue.forEach((item, index) => {
432	      const timerId = window.setTimeout(
433	        () => {
434	          item.classList.add(INIT_DOM_CLASSES.blockBase);
435	          item.classList.remove(INIT_DOM_CLASSES.boxHidden);
436	          if (shouldShow) {
437	            item.classList.remove("is-block-reveal-down");
438	            BlockReveal.reveal(item);
439	            return;
440	          }
441	          item.classList.remove(INIT_DOM_CLASSES.blockUp);
442	          item.classList.add("is-block-reveal-down");
443	        },
444	        index * delayStep * 1000,
445	      );
446	      mainSceneDomState.contactActionTimers.push(timerId);
447	    });
448	  }
449	
450	  if (mainSceneDomState.isContactHeadVisible === shouldShow) return;
451	  mainSceneDomState.isContactHeadVisible = shouldShow;
452	  mainSceneDomState.contactHeadTimers = clearTimers(
453	    mainSceneDomState.contactHeadTimers,
454	  );
455	
456	  if (shouldShow) {
457	    section.dataset.active = "true";
458	    head.dataset.active = "true";
459	    actions.dataset.active = "true";
460	    TextReveal.setVisibleOff(textItems);
461	    textItems.forEach((item, index) => {
462	      const timerId = window.setTimeout(
463	        () => {
464	          TextReveal.setVisibleOn(item);
465	        },
466	        index * CONTACT_HEAD_TRANSITION.revealStagger * 1000,
467	      );
468	      mainSceneDomState.contactHeadTimers.push(timerId);
469	    });
470	    return;
471	  }
472	
473	  textItems
474	    .slice()
475	    .reverse()
476	    .forEach((item, index) => {
477	      const timerId = window.setTimeout(
478	        () => {
479	          TextReveal.setVisibleOff(item);
480	        },
481	        index * CONTACT_HEAD_TRANSITION.hideStagger * 1000,
482	      );
483	      mainSceneDomState.contactHeadTimers.push(timerId);
484	    });
485	
486	  const hideTimerId = window.setTimeout(
487	    () => {
488	      section.dataset.active = "false";
489	      head.dataset.active = "false";
490	      actions.dataset.active = "false";
491	    },
492	    (Math.max(textItems.length - 1, 0) *
493	      CONTACT_HEAD_TRANSITION.hideStagger +
494	      CONTACT_HEAD_TRANSITION.hideSettleDuration) *
495	      1000,
496	  );
497	  mainSceneDomState.contactHeadTimers.push(hideTimerId);
498	}
